M10_DATA_SOURCE="#@title MISIÓN 06 · 1. Datos autorizados, índice nuevo y normalización causal\nassert globals().get('M6_PREFLIGHT_OK') is True, 'Ejecutar primero M06 · 0'\nimport numpy as np\nimport pandas as pd\n\nM6_SOURCE = M6_BASE / 'datasets/processed/kronos_ohlcv_v1'\nM6_SOURCE_MANIFEST, m6_parts = [], []\n# Lista cerrada; no se enumeran directorios de datos, archivos ZIP ni índices históricos.\ndef m6_authorized_source(year):\n    if type(year) is not int or year not in range(2010, 2021):\n        raise ValueError('M06 solo permite archivos fuente 2010–2020')\n    return M6_SOURCE / f'XAUUSD_M15_BID_{year}.parquet'\n\nfor m6_year in range(2010, 2021):\n    m6_path = m6_authorized_source(m6_year)\n    m6_digest = m6_sha(m6_path)\n    m6_part = pd.read_parquet(m6_path)\n    m6_part['timestamp_utc'] = pd.to_datetime(m6_part.timestamp_utc, utc=True)\n    assert len(m6_part) and m6_part.timestamp_utc.dt.year.eq(m6_year).all()\n    assert m6_part.timestamp_utc.is_monotonic_increasing and m6_part.timestamp_utc.is_unique\n    assert m6_part.m1_candles.eq(15).all()\n    m6_prices = m6_part[['open', 'high', 'low', 'close', 'volume']]\n    assert np.isfinite(m6_prices.to_numpy()).all()\n    assert (m6_part.low > 0).all() and (m6_part.volume >= 0).all()\n    assert (m6_part.low <= m6_part[['open', 'close']].min(axis=1)).all()\n    assert (m6_part.high >= m6_part[['open', 'close']].max(axis=1)).all()\n    assert (m6_part.low <= m6_part.high).all()\n    assert m6_sha(m6_path) == m6_digest, 'Fuente cambió durante lectura'\n    M6_SOURCE_MANIFEST.append({'year': m6_year, 'file': m6_path.name, 'rows': len(m6_part), 'sha256': m6_digest})\n    m6_parts.append(m6_part[['timestamp_utc', 'open', 'high', 'low', 'close', 'volume']].copy())\nm6_df = pd.concat(m6_parts, ignore_index=True)\ndel m6_parts, m6_part, m6_prices\nassert m6_df.timestamp_utc.is_unique and m6_df.timestamp_utc.is_monotonic_increasing\nm6_ts = m6_df.timestamp_utc.astype('int64').to_numpy()\nM6_STEP = 15 * 60 * 10**9\nassert np.all(m6_ts % M6_STEP == 0)\nm6_df['split'] = np.where(m6_df.timestamp_utc.dt.year <= 2019, 'train', 'development')\nm6_df['segment'] = (m6_df.timestamp_utc.diff().ne(pd.Timedelta(minutes=15)) |\n                    m6_df.split.ne(m6_df.split.shift())).cumsum()\nm6_windows = []\nfor m6_segment, m6_group in m6_df.groupby('segment', sort=False):\n    m6_first, m6_last = int(m6_group.index[0]), int(m6_group.index[-1])\n    m6_starts = np.arange(m6_first, m6_last - 59 + 1, dtype=np.int64)\n    if not len(m6_starts):\n        continue\n    m6_decisions = m6_df.timestamp_utc.iloc[m6_starts + 56]\n    m6_ny = m6_decisions.dt.tz_convert('America/New_York')\n    for s, decision, ny in zip(m6_starts, m6_decisions, m6_ny):\n        if ny.strftime('%H:%M') not in M6_POLICY['ny_anchors']:\n            continue\n        m6_windows.append({'start_row': int(s), 'split': m6_group.split.iloc[0],\n                           'decision_utc': decision, 'decision_ny': ny.isoformat(),\n                           'ny_date': ny.strftime('%Y-%m-%d'), 'ny_hour': ny.strftime('%H:%M'),\n                           'context_start': m6_df.timestamp_utc.iloc[s],\n                           'target_end': m6_df.timestamp_utc.iloc[s+59] + pd.Timedelta(minutes=15)})\nm6_ix = pd.DataFrame(m6_windows).sort_values('decision_utc').reset_index(drop=True)\nassert len(m6_ix) and m6_ix.decision_utc.is_unique\nm6_train_ix = m6_ix[m6_ix.split.eq('train')].reset_index(drop=True)\nm6_dev_ix = m6_ix[m6_ix.split.eq('development')].reset_index(drop=True)\nassert len(m6_train_ix) and len(m6_dev_ix)\nassert m6_dev_ix.decision_utc.dt.year.eq(2020).all()\nassert m6_train_ix.target_end.max() < m6_dev_ix.context_start.min()\nassert (m6_ix.decision_utc.iloc[1:].to_numpy() >= m6_ix.target_end.iloc[:-1].to_numpy()).all()\nm6_starts = m6_ix.start_row.to_numpy(np.int64)\nassert np.all(m6_ts[m6_starts[:, None] + np.arange(60)] == m6_ts[m6_starts, None] + np.arange(60) * M6_STEP)\n\ndef m6_normalize(raw):\n    raw = np.asarray(raw, dtype=np.float32)\n    if raw.shape != (60, 6):\n        raise ValueError('Contrato M06: 60 filas, OHLCV + amount=0')\n    mean = raw[:56].mean(axis=0)\n    scale = raw[:56].std(axis=0) + np.float32(1e-5)\n    return np.clip((raw - mean) / scale, -5, 5), mean, scale\n\nclass M6Dataset(torch.utils.data.Dataset):\n    def __init__(self, frame, index):\n        self.L, self.H = 56, 4\n        self.index = index.reset_index(drop=True)\n        self.starts = self.index.start_row.to_numpy(np.int64)\n        self.values = np.column_stack([frame[['open','high','low','close','volume']].to_numpy(np.float32), np.zeros(len(frame), np.float32)])\n        t = frame.timestamp_utc.dt\n        self.stamp = np.column_stack([t.minute, t.hour, t.weekday, t.day, t.month]).astype(np.float32)\n    def __len__(self):\n        return len(self.starts)\n    def __getitem__(self, i):\n        s = int(self.starts[i])\n        raw = self.values[s:s+60].copy()\n        x, mean, scale = m6_normalize(raw)\n        return {'x': torch.from_numpy(x), 'stamp': torch.from_numpy(self.stamp[s:s+60].copy()),\n                'loss_mask': torch.from_numpy(np.arange(59) >= 55),\n                'mean': torch.from_numpy(mean), 'scale': torch.from_numpy(scale),\n                'truth': torch.from_numpy(raw[56:].copy()), 'last_close': torch.tensor(raw[55,3])}\n\nm6_train = M6Dataset(m6_df, m6_train_ix)\nm6_dev = M6Dataset(m6_df, m6_dev_ix)\nm6_probe = m6_train.values[m6_train.starts[0]:m6_train.starts[0]+60].copy()\nm6_changed = m6_probe.copy()\nm6_changed[56:] += np.float32(10000)\nm6_before, m6_after = m6_normalize(m6_probe), m6_normalize(m6_changed)\nassert np.array_equal(m6_before[0][:56], m6_after[0][:56])\nassert np.array_equal(m6_before[1], m6_after[1]) and np.array_equal(m6_before[2], m6_after[2])\nM6_DATA_CHECKS = {'loaded_years': list(range(2010, 2021)), 'normalization_future_invariant': True,\n                  'train_windows': len(m6_train), 'development_windows': len(m6_dev),\n                  'development_ny_sessions': int(m6_dev_ix.ny_date.nunique()),\n                  'causal_model_checks': 'PENDING', 'predictive_experiments': 'NOT_EXECUTED'}\n"
M10_ACTIVITY_SOURCE="# M09_ACTIVITY_GATE_V4\ndef m09_activity_gate(namespace):\n    import datetime, json, os, subprocess, sys, threading, time\n    from pathlib import Path\n    report={'timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),\n            'pid':os.getpid(),'samples':[],'blockers':[],'training_active':'UNKNOWN',\n            'optimizer_steps':0,'test_read':False,'orders_enabled':False}\n    current=threading.get_ident()\n    safe_modules=('threading','queue','asyncio','selectors','concurrent.futures','zmq','tornado',\n                  'ipykernel','IPython','google.colab','traitlets','logging','jupyter_client',\n                  'debugpy','pydevd','_pydev','multiprocessing','prompt_toolkit','anyio')\n    def process_inventory():\n        rows=[]\n        for entry in Path('/proc').iterdir():\n            if not entry.name.isdigit():continue\n            try:\n                comm=(entry/'comm').read_text().strip()\n                if not any(x in comm.lower() for x in ('python','torchrun','accelerate','deepspeed')):continue\n                args=(entry/'cmdline').read_bytes().decode(errors='replace').split('\\0')\n                pid=int(entry.name)\n                category='CURRENT_KERNEL' if pid==os.getpid() else 'UNCLASSIFIED'\n                # Classify known Colab infrastructure without printing command arguments/secrets.\n                for module in ('colab_kernel_launcher','google.colab._server','jupyter_http_over_ws','jupyter_server','notebook.notebookapp'):\n                    if any(module in arg for arg in args):\n                        if pid!=os.getpid():category='COLAB_SERVICE:'+module\n                if pid!=os.getpid() and any(Path(arg).name in ('jupyter-notebook','jupyter-server') for arg in args):category='JUPYTER_SERVICE'\n                entrypoint='UNKNOWN'\n                args=[args[0]]+[arg for arg in args[1:] if arg not in ('-u','-B','-E','-s','-S','-I','-O','-OO')]\n                if len(args)>2 and args[1]=='-m':entrypoint=args[2]\n                elif len(args)>1 and not args[1].startswith('-'):entrypoint=args[1]\n                elif len(args)>1 and args[1]=='-c':entrypoint='INLINE_CODE_REQUIRES_REVIEW'\n                allowed_services={'/opt/google/drive/drive-filter.py','/usr/local/bin/colab-fileshim.py','debugpy.adapter','google.colab._kernel_launcher','google.colab._server'}\n                if pid!=os.getpid() and entrypoint in allowed_services:category='VERIFIED_SERVICE_ENTRYPOINT'\n                if pid!=os.getpid() and entrypoint.endswith('/debugpy/adapter') and entrypoint.startswith('/usr/local/lib/'):category='DEBUGPY_ADAPTER'\n                maps=(entry/'maps').read_text()\n                torch_cuda_maps=sorted(set(line.split()[-1] for line in maps.splitlines() if any(marker in line.lower() for marker in ('libtorch','libc10','/torch/','libcuda','libcudart'))))\n                if category=='UNCLASSIFIED' and not torch_cuda_maps:category='PYTHON_WITHOUT_TORCH_OR_CUDA_MAPPINGS'\n                rows.append({'pid':pid,'name':comm,'category':category,'entrypoint':entrypoint,'entrypoint_exists':Path(entrypoint).is_file() if entrypoint.startswith('/') else None,'torch_cuda_mapped_libraries':torch_cuda_maps})\n            except FileNotFoundError:continue\n            except PermissionError:rows.append({'pid':int(entry.name),'category':'UNREADABLE'})\n        return rows\n    for sample_index in range(3):\n        frames=sys._current_frames();threads=[]\n        for thread in threading.enumerate():\n            if thread.ident==current:continue\n            frame=frames.get(thread.ident);stack=[]\n            while frame is not None:\n                module=str(frame.f_globals.get('__name__',''))\n                stack.append({'module':module,'function':frame.f_code.co_name})\n                frame=frame.f_back\n            unknown=[x for x in stack if not x['module'].startswith(safe_modules) and (x['module'],x['function']) not in {('pexpect.popen_spawn','_read_incoming'),('tqdm._monitor','run')}]\n            training=[x for x in stack if x['module'].startswith(('torch.optim','torch.autograd')) or x['function'] in ('backward','train_step','training_step','fit')]\n            threads.append({'name':thread.name,'alive':thread.is_alive(),'stack':stack,'unclassified_frames':unknown,'training_frames':training})\n        del frames\n        command=subprocess.run(['nvidia-smi','--query-compute-apps=pid,used_gpu_memory','--format=csv,noheader,nounits'],capture_output=True,text=True,timeout=15,check=True)\n        gpu=[]\n        for line in command.stdout.splitlines():\n            parts=[x.strip() for x in line.split(',')]\n            if parts and parts[0].isdigit():gpu.append({'pid':int(parts[0]),'used_memory_mib':parts[1] if len(parts)>1 else None})\n        processes=process_inventory()\n        report['samples'].append({'timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'threads':threads,'gpu_processes':gpu,'python_processes':processes})\n        if any(t['training_frames'] for t in threads):report['blockers'].append('Training stack observed')\n        if any(t['unclassified_frames'] for t in threads):report['blockers'].append('Unclassified background Python stack')\n        if any(p['pid']!=os.getpid() for p in gpu):report['blockers'].append('Other GPU process active')\n        if any(p['category'] in ('UNCLASSIFIED','UNREADABLE') for p in processes):report['blockers'].append('Unclassified Python process')\n        if sample_index<2:time.sleep(2)\n    session=namespace.get('AXXEL_SESSION')\n    report['session_present']=bool(session)\n    if not session:report['blockers'].append('AXXEL_SESSION absent')\n    else:\n        nets=[session['model'],session['tokenizer'],*session['heads'].values()]\n        report['session_frozen']=all(not p.requires_grad and p.grad is None for net in nets for p in net.parameters())\n        if not report['session_frozen']:report['blockers'].append('Production session not frozen or has gradients')\n    report['blockers']=sorted(set(report['blockers']))\n    if not report['blockers']:report['training_active']=False\n    report['status']='PASS_CURRENT_ACTIVITY' if not report['blockers'] else 'BLOCKED'\n    report['scope']='Three current samples: no active Kronos/PyTorch training in kernel stacks or other Python/GPU processes; library mappings classify otherwise unknown Python processes. Does not certify unrelated CPU frameworks or future scheduling.'\n    print('M09_ACTIVITY_V4_RESULT '+json.dumps(report),flush=True)\n    return report"
M10_EVALUATION_SOURCE='"""Fixed development evaluation for M06_FV_JOINT_RETURN_V1; no model fitting."""\ndef m10_evaluate(out,root,protocol,predictions,references,truth,last,index,curves,timings):\n    import datetime,hashlib,io,json,math\n    import numpy as np\n    import pandas as pd\n    import matplotlib.pyplot as plt\n    from IPython.display import display\n    folder=out/\'evaluation\'/datetime.datetime.now(datetime.timezone.utc).strftime(\'%Y%m%dT%H%M%S%fZ\')\n    folder.mkdir(parents=True,exist_ok=False)\n    def save_json(name,value):\n        with (folder/name).open(\'x\') as f:json.dump(value,f,indent=2,allow_nan=False)\n    def stats(p,y=truth,l=last):\n        err=p-y;actual=y-l[:,None];forecast=p-l[:,None];valid=actual!=0\n        return {\'MAE\':float(abs(err).mean()),\'RMSE\':float(np.sqrt((err**2).mean())),\n                \'bias\':float(err.mean()),\'direction_error\':float((np.sign(actual[valid])!=np.sign(forecast[valid])).mean()),\n                \'direction_accuracy\':float((np.sign(actual[valid])==np.sign(forecast[valid])).mean()),\n                \'magnitude_MAE\':float(abs(abs(forecast)-abs(actual)).mean()),\n                \'MAE_by_horizon\':abs(err).mean(0).tolist()}\n    refs=dict(references)\n    # Reuse audited greedy baseline only when its checksum is available; never recompute an old experiment.\n    baseline_paths=[root/\'metricas/Kronos_base.parquet\',root/\'fase_I/metricas/Kronos_base.parquet\']\n    baseline_status=\'UNAVAILABLE_UNVERIFIED\'\n    for path in baseline_paths:\n        if not path.exists():continue\n        for manifest_path in (root/\'checksums.json\',root/\'fase_I/checksums.json\'):\n            if not manifest_path.exists():continue\n            manifest=json.loads(manifest_path.read_text())\n            try:relative=str(path.relative_to(manifest_path.parent))\n            except ValueError:continue\n            entry=manifest.get(relative)\n            if entry is None:continue\n            expected=entry.get(\'sha256\') if isinstance(entry,dict) else entry\n            assert hashlib.sha256(path.read_bytes()).hexdigest()==expected,\'Greedy reference hash mismatch\'\n            frame=pd.read_parquet(path)\n            actual=frame.pivot(index=\'window\',columns=\'horizon\',values=\'truth\').sort_index().to_numpy()\n            assert np.array_equal(actual,truth)\n            refs[\'Kronos_base\']=frame.pivot(index=\'window\',columns=\'horizon\',values=\'prediction\').sort_index().to_numpy()\n            baseline_status=\'VERIFIED\';break\n        if baseline_status==\'VERIFIED\':break\n    all_predictions={**refs,**predictions}\n    table={name:stats(p) for name,p in all_predictions.items()}\n    per_hour=[]\n    for name,p in all_predictions.items():\n        for hour in sorted(index.ny_hour.unique()):\n            ids=np.flatnonzero(index.ny_hour.eq(hour))\n            per_hour.append({\'model\':name,\'hour\':hour,**stats(p[ids],truth[ids],last[ids])})\n    sessions=sorted(index.ny_date.unique());session_ids=[np.flatnonzero(index.ny_date.eq(s)) for s in sessions]\n    assert len(sessions)==243\n    rng=np.random.default_rng(271828);B=10000;block=5;S=len(sessions)\n    starts=rng.integers(0,S,size=(B,math.ceil(S/block)))\n    samples=((starts[:,:,None]+np.arange(block))%S).reshape(B,-1)[:,:S]\n    counts=np.array([len(ids)*4 for ids in session_ids]);denominator=counts[samples].sum(1)\n    paired=[];gate=True\n    for seed in protocol[\'seeds\']:\n        candidate=f\'joint_QV_head_s{seed}\';pred=predictions[candidate]\n        for reference in (\'Persistencia\',\'Head_Huber_s271830\',f\'control_head_only_s{seed}\'):\n            ref=all_predictions[reference]\n            delta=abs(pred-truth)-abs(ref-truth)\n            sums=np.array([delta[ids].sum() for ids in session_ids])\n            distribution=sums[samples].sum(1)/denominator\n            ci95=np.quantile(distribution,[.025,.975]);ci_sim=np.quantile(distribution,[.05/9/2,1-.05/9/2])\n            horizon=delta.mean(0);hours=[float(delta[np.flatnonzero(index.ny_hour.eq(h))].mean()) for h in sorted(index.ny_hour.unique())]\n            passed=bool(delta.mean()<0 and ci_sim[1]<0 and max(horizon)<=0 and max(hours)<=0)\n            gate=gate and passed\n            paired.append({\'candidate\':candidate,\'reference\':reference,\'delta_MAE\':float(delta.mean()),\n                           \'CI95\':ci95.tolist(),\'CI_simultaneous_Bonferroni9\':ci_sim.tolist(),\n                           \'delta_by_horizon\':horizon.tolist(),\'delta_by_hour\':hours,\'followup_component_passed\':passed})\n    dispersion={}\n    for arm in (\'control_head_only\',\'joint_QV_head\'):\n        values=[table[f\'{arm}_s{s}\'][\'MAE\'] for s in protocol[\'seeds\']]\n        dispersion[arm]={\'seed_MAEs\':values,\'mean\':float(np.mean(values)),\'std_ddof1\':float(np.std(values,ddof=1))}\n    save_json(\'metrics.json\',table);save_json(\'metrics_by_NY_hour.json\',per_hour);save_json(\'paired_bootstrap.json\',paired);save_json(\'seed_dispersion.json\',dispersion)\n    pd.DataFrame([{\'model\':name,**{k:v for k,v in metrics.items() if k!=\'MAE_by_horizon\'}} for name,metrics in table.items()]).to_csv(folder/\'metrics.csv\',index=False)\n    # Six plots from measured quantities. Development points exist only at 0 and 300.\n    plot_files=[]\n    def finish(name):\n        fig=plt.gcf();fig.tight_layout();fig.savefig(folder/name,dpi=150,bbox_inches=\'tight\');display(fig);plt.close(fig);plot_files.append(name)\n    fig,axes=plt.subplots(1,2,figsize=(13,4))\n    for arm,ax in zip((\'control_head_only\',\'joint_QV_head\'),axes):\n        for seed in protocol[\'seeds\']:\n            name=f\'{arm}_s{seed}\';c=curves[name]\n            ax.plot([x[\'step\'] for x in c],[x[\'loss\'] for x in c],alpha=.75,label=f\'train {seed}\')\n            run=out/arm/f\'seed_{seed}\'\n            dev0=json.loads((run/\'step0_metrics.json\').read_text())[\'loss\'];dev300=json.loads((run/\'final_metrics.json\').read_text())[\'loss\']\n            ax.scatter([0,300],[dev0,dev300],marker=\'x\',s=45,label=f\'dev endpoints {seed}\')\n        ax.set(title=arm,xlabel=\'Optimizer step\',ylabel=\'Scaled-return Huber\');ax.legend(fontsize=6)\n    finish(\'01_training_validation.png\')\n    plt.figure(figsize=(9,4));names=[\'Persistencia\',\'Head_Huber_s271830\',*predictions]\n    plt.bar(range(len(names)),[table[n][\'MAE\'] for n in names]);plt.xticks(range(len(names)),names,rotation=45,ha=\'right\',fontsize=7);plt.ylabel(\'MAE price\');finish(\'02_MAE_architectures.png\')\n    plt.figure(figsize=(9,4))\n    for name in names:plt.plot(range(1,5),table[name][\'MAE_by_horizon\'],marker=\'o\',label=name)\n    plt.xticks(range(1,5));plt.xlabel(\'Horizon (15 min)\');plt.ylabel(\'MAE price\');plt.legend(fontsize=6);finish(\'03_MAE_horizons.png\')\n    plt.figure(figsize=(11,4));x=np.arange(40)\n    plt.plot(x,truth[:40,3],color=\'black\',label=\'True H4 close\')\n    for name in (\'Persistencia\',\'control_head_only_s271828\',\'joint_QV_head_s271828\'):plt.plot(x,all_predictions[name][:40,3],label=name,alpha=.8)\n    plt.xlabel(\'First 40 development decision windows (fixed slice)\');plt.ylabel(\'XAUUSD price\');plt.legend(fontsize=7);finish(\'04_prediction_vs_actual.png\')\n    plt.figure(figsize=(9,4))\n    for name in predictions:plt.hist((predictions[name]-truth).ravel(),bins=70,histtype=\'step\',density=True,label=name)\n    plt.xlabel(\'Prediction minus true price\');plt.ylabel(\'Density\');plt.legend(fontsize=6);finish(\'05_error_distribution.png\')\n    fig,ax=plt.subplots(figsize=(10,6))\n    for i,row in enumerate(paired):\n        lo,hi=row[\'CI_simultaneous_Bonferroni9\'];ax.plot([lo,hi],[i,i],color=\'tab:blue\');ax.scatter(row[\'delta_MAE\'],i,color=\'black\',s=15)\n    ax.axvline(0,color=\'red\',linestyle=\'--\');ax.set_yticks(range(9),[r[\'candidate\']+\' - \'+r[\'reference\'] for r in paired],fontsize=7);ax.set_xlabel(\'Paired delta MAE; simultaneous intervals across 9 contrasts\');finish(\'06_paired_intervals.png\')\n    conclusion={\'candidate_followup_gate\':bool(gate),\'independent_holdout\':False,\n                \'superiority_claim\':\'No independent predictive superiority claim: development 2020 was reused for prior selection.\',\n                \'bootstrap\':protocol[\'evaluation\'][\'bootstrap\'],\'baseline_status\':baseline_status}\n    save_json(\'conclusion.json\',conclusion)\n    report=\'# Phase V: Joint LoRA + Huber\\n\\nDevelopment 2020 only; no test access.\\n\\n\'\n    report+=\'|Model|MAE|RMSE|Bias|Direction error|\\n|---|---:|---:|---:|---:|\\n\'\n    for name,m in table.items():report+=f"|{name}|{m[\'MAE\']:.9f}|{m[\'RMSE\']:.9f}|{m[\'bias\']:.9f}|{m[\'direction_error\']:.6f}|\\n"\n    report+=\'\\nFollow-up gate: \'+str(gate)+\'. \'+conclusion[\'superiority_claim\']+\'\\n\'\n    report+=\'\\nPaired bootstrap: circular blocks of five NY sessions, 10,000 replicates, simultaneous Bonferroni bounds for nine fixed contrasts.\\n\'\n    with (folder/\'report.md\').open(\'x\') as f:f.write(report)\n    manifest={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in folder.iterdir() if p.is_file()}\n    save_json(\'checksums.json\',manifest)\n    display(pd.DataFrame([{\'model\':n,\'MAE\':m[\'MAE\'],\'RMSE\':m[\'RMSE\']} for n,m in table.items()]))\n    return {\'directory\':str(folder),\'metrics\':table,\'paired_comparisons\':paired,\'seed_dispersion\':dispersion,\n            \'followup_gate\':bool(gate),\'figures\':plot_files,\'manifest_sha256\':hashlib.sha256((folder/\'checksums.json\').read_bytes()).hexdigest(),\'baseline_status\':baseline_status}\n'
M10_BODY_SOURCE='# M10_PHASE_V_JOINT_RETURN_V1\n"""Explicitly authorized six-run experiment; never invoked by daily start.\nConfiguration, audited data source, activity check and source hashes are embedded by builder.\n"""\ndef m10_execute(session):\n    import copy, datetime, gc, hashlib, io, json, math, os, random, time, traceback\n    from pathlib import Path\n    import numpy as np\n    import pandas as pd\n    import torch\n    from torch import nn\n    from torch.nn import functional as F\n    from torch.utils.data import default_collate\n\n    P=M10_PROTOCOL\n    assert M10_AUTHORIZED is True and P[\'experiment\']==\'M06_FV_JOINT_RETURN_V1\'\n    assert P[\'budget\'][\'additional_steps_each\']==300 and P[\'budget\'][\'microbatch\']==16 and P[\'budget\'][\'accumulation\']==4\n    assert P[\'seeds\']==[271828,271829,271830] and P[\'optimizer\'][\'weight_decay\']==0\n    root=Path(P[\'canonical_run\'])\n    result={\'timestamp_utc\':datetime.datetime.now(datetime.timezone.utc).isoformat(),\'status\':\'RUNNING\',\'runs\':[],\n            \'test_read\':False,\'orders_enabled\':False,\'training_authorized\':True}\n    def digest(path):\n        h=hashlib.sha256()\n        with Path(path).open(\'rb\') as f:\n            for b in iter(lambda:f.read(1048576),b\'\'):h.update(b)\n        return h.hexdigest()\n    def canonical(value):return json.dumps(value,sort_keys=True,separators=(\',\',\':\'),allow_nan=False).encode()\n    def net_hash(net,exclude_lora=False):\n        h=hashlib.sha256()\n        for name,t in sorted(net.state_dict().items()):\n            if exclude_lora and \'lora_\' in name:continue\n            name=name.replace(\'.base.\', \'.\') if exclude_lora else name\n            h.update(name.encode());h.update(str(tuple(t.shape)).encode());h.update(t.detach().cpu().contiguous().numpy().tobytes())\n        return h.hexdigest()\n    def put(path,data):\n        path=Path(path)\n        if path.exists():\n            assert path.read_bytes()==data,\'Conflicting existing artifact: \'+str(path)\n            return\n        path.parent.mkdir(parents=True,exist_ok=True)\n        with path.open(\'xb\') as f:f.write(data);f.flush();os.fsync(f.fileno())\n        assert digest(path)==hashlib.sha256(data).hexdigest()\n    def put_json(path,data):put(path,canonical(data))\n    def put_npz(path,**arrays):\n        b=io.BytesIO();np.savez_compressed(b,**arrays);put(path,b.getvalue())\n    def load_json(path):return json.loads(Path(path).read_text())\n    def progress(**values):print(\'M10_PROGRESS \'+json.dumps(values),flush=True)\n\n    # Repeat only volatile readiness checks; historical experiments are never invoked.\n    activity_ns={\'__name__\':\'m10_activity\'}\n    exec(compile(M10_ACTIVITY_SOURCE,\'m10_activity\',\'exec\'),activity_ns)\n    activity=activity_ns[\'m09_activity_gate\']({\'AXXEL_SESSION\':session})\n    assert activity[\'status\']==\'PASS_CURRENT_ACTIVITY\',activity[\'blockers\']\n    assert os.path.ismount(\'/content/drive\') and torch.cuda.is_available()\n    base,tok=session[\'model\'],session[\'tokenizer\']\n    assert net_hash(base)==P[\'base_hash\'] and net_hash(tok)==P[\'tokenizer_hash\']\n    assert all(not p.requires_grad and p.grad is None for net in (base,tok) for p in net.parameters())\n    assert digest(root/\'informes/PROTOCOLO_FASE_V_JOINT_PROPUESTO_20261120.json\')==M10_PROTOCOL_SHA\n    manifest3=load_json(root/\'fase_III/checksums.json\')\n    assert digest(root/\'fase_III/checksums.json\')==\'731d1c5412d4836e16961ff2e3747e6fd4da124db81eaf20265a638b6c90d7a1\'\n    def verified3(relative):\n        p=root/\'fase_III\'/relative\n        assert digest(p)==manifest3[relative][\'sha256\'],str(p)\n        return p\n    for seed in P[\'seeds\']:\n        init=P[\'head_initialization\'][str(seed)]\n        assert digest(init[\'path\'])==init[\'sha256\']\n        packet=torch.load(init[\'path\'],map_location=\'cpu\',weights_only=True)\n        assert all(torch.equal(v.cpu(),packet[\'head\'][k]) for k,v in session[\'heads\'][seed].state_dict().items())\n\n    science=copy.deepcopy(P)\n    for k in (\'created_date_Bogota\',\'status\',\'purpose\',\'canonical_run\',\'output_subdirectory_proposed\',\'training_started\'):science.pop(k,None)\n    for head in science[\'head_initialization\'].values():head.pop(\'path\');head.pop(\'model\')\n    science[\'execution_source_sha256\']=M10_SOURCE_SHA\n    science[\'data_code_sha256\']=hashlib.sha256(M10_DATA_SOURCE.encode()).hexdigest()\n    fingerprint=hashlib.sha256(canonical(science)).hexdigest()\n    registry=root/\'fase_V_joint_v1\'\n    registry.mkdir(exist_ok=True)\n    # Any prior registry entry for this protocol with changed code/config is a conflict, not a fresh run.\n    for folder in registry.iterdir():\n        assert folder.is_dir() and (folder/\'config.json\').is_file(),\'Untracked Phase V artifact: \'+str(folder)\n        assert folder.name==fingerprint and load_json(folder/\'config.json\')==science,\'Existing Phase V configuration conflict\'\n    out=registry/fingerprint\n    out.mkdir(exist_ok=True)\n    put_json(out/\'config.json\',science)\n    put(out/\'training_source.py\',M10_BODY_SOURCE.encode())\n    put(out/\'data_source.py\',M10_DATA_SOURCE.encode())\n    put(out/\'evaluation_source.py\',M10_EVALUATION_SOURCE.encode())\n    put(out/\'activity_source.py\',M10_ACTIVITY_SOURCE.encode())\n    put_json(out/\'protocol_original.json\',P)\n    result[\'artifact_directory\']=str(out);result[\'scientific_fingerprint\']=fingerprint\n    attempt=datetime.datetime.now(datetime.timezone.utc).strftime(\'%Y%m%dT%H%M%S%fZ\')\n    lock=out/\'active.lock\'\n    owner={\'pid\':os.getpid(),\'attempt\':attempt,\'boot_id\':Path(\'/proc/sys/kernel/random/boot_id\').read_text().strip()}\n    if lock.exists():raise RuntimeError(\'Existing execution lock: inspect persisted state before resuming\')\n    with lock.open(\'x\') as f:json.dump(owner,f)\n    saved_rng=(random.getstate(),np.random.get_state(),torch.get_rng_state(),torch.cuda.get_rng_state_all())\n    old_deterministic=torch.are_deterministic_algorithms_enabled()\n    old_tf32=(torch.backends.cuda.matmul.allow_tf32,torch.backends.cudnn.allow_tf32)\n    try:\n        os.environ.setdefault(\'CUBLAS_WORKSPACE_CONFIG\',\':4096:8\')\n        torch.use_deterministic_algorithms(True)\n        torch.backends.cuda.matmul.allow_tf32=False;torch.backends.cudnn.allow_tf32=False\n        base.eval();tok.eval()\n        put_json(out/f\'attempts/{attempt}/activity.json\',activity)\n        put_json(out/f\'attempts/{attempt}/environment.json\',{\'torch\':str(torch.__version__),\'cuda\':torch.version.cuda,\'gpu\':torch.cuda.get_device_name(),\'free_total_bytes\':torch.cuda.mem_get_info()})\n        ns={\'__name__\':\'m10_authorized_data\',\'M6_PREFLIGHT_OK\':True,\'M6_BASE\':root.parents[1],\'M6_DIR\':root,\n            \'M6_POLICY\':load_json(root/\'configuraciones/politica.json\'),\'torch\':torch,\'m6_sha\':digest}\n        assert ns[\'M6_POLICY\'][\'allowed_source_years\']==list(range(2010,2021))\n        exec(compile(M10_DATA_SOURCE,\'m10_authorized_data\',\'exec\'),ns)\n        assert digest(root/\'auditoria/datasets_autorizados.json\')==P[\'data\'][\'source_manifest_sha256\']\n        assert ns[\'M6_SOURCE_MANIFEST\']==load_json(root/\'auditoria/datasets_autorizados.json\')\n        pd.testing.assert_frame_equal(ns[\'m6_ix\'],pd.read_parquet(root/\'auditoria/ventanas_m06.parquet\'))\n        train,dev=ns[\'m6_train\'],ns[\'m6_dev\'];dev_index=ns[\'m6_dev_ix\']\n        assert len(train)==8428 and len(dev)==950 and dev_index.ny_date.nunique()==243\n        scalers=session[\'scalers\']\n        scaler_path=verified3(\'checkpoints/fase_III/7587400db64558e6/train_only_scalers.npz\')\n        assert digest(scaler_path)==P[\'shared_model\'][\'scalers_sha256\']\n        with np.load(scaler_path,allow_pickle=False) as z:\n            assert all(np.array_equal(scalers[k],z[k]) for k in z.files)\n        mean=torch.as_tensor(scalers[\'hidden_mean\'],device=\'cuda\')\n        scale=torch.as_tensor(scalers[\'hidden_scale\'],device=\'cuda\')\n        ret_scale=torch.as_tensor(scalers[\'return_scale\'],device=\'cuda\')\n        def normalize(h):return ((h.double()-mean).float().double()/scale).float()\n        def encode_dataset(ds):\n            packs={k:[] for k in (\'a\',\'b\',\'stamp\',\'features\',\'truth\',\'last\',\'target\')}\n            with torch.no_grad():\n                for i in range(0,len(ds),16):\n                    b={k:v.cuda() for k,v in default_collate([ds[j] for j in range(i,min(i+16,len(ds)))]).items()}\n                    a,c=tok.encode(b[\'x\'][:,:56],half=True)\n                    stamp=b[\'stamp\'][:,:56]\n                    h=base.decode_s1(a,c,stamp=stamp)[1][:,-1]\n                    truth=b[\'truth\'][:,:,3].double();last=b[\'last_close\'].double()\n                    target=(10000*(truth/last[:,None]-1)/ret_scale).float()\n                    for key,value in zip(packs,(a,c,stamp,normalize(h),truth,last,target)):packs[key].append(value.detach())\n            return {k:torch.cat(v) for k,v in packs.items()}\n        progress(stage=\'encoding_context_only\',train_windows=len(train),dev_windows=len(dev))\n        caches={\'train\':encode_dataset(train),\'dev\':encode_dataset(dev)}\n        truth=caches[\'dev\'][\'truth\'].cpu().numpy();last=caches[\'dev\'][\'last\'].cpu().numpy()\n        put_npz(out/\'development_index.npz\',truth=truth,last=last,session=dev_index.ny_date.to_numpy(dtype=str),hour=dev_index.ny_hour.to_numpy(dtype=str),decision=dev_index.decision_utc.astype(str).to_numpy(dtype=str))\n\n        class LoRA(nn.Module):\n            def __init__(self,layer):\n                super().__init__();self.base=layer.requires_grad_(False)\n                self.lora_A=nn.Parameter(torch.empty(8,layer.in_features,device=\'cuda\'))\n                self.lora_B=nn.Parameter(torch.zeros(layer.out_features,8,device=\'cuda\'))\n                self.dropout=nn.Dropout(.1);nn.init.kaiming_uniform_(self.lora_A,a=math.sqrt(5))\n            def forward(self,x):return self.base(x)+2*F.linear(F.linear(self.dropout(x),self.lora_A),self.lora_B)\n        def features(net,cache,ids,joint):\n            if not joint:return cache[\'features\'][ids]\n            return normalize(net.decode_s1(cache[\'a\'][ids],cache[\'b\'][ids],stamp=cache[\'stamp\'][ids])[1][:,-1])\n        def mode(net,head,training):\n            net.eval();head.train(training)\n            for module in net.modules():\n                if isinstance(module,LoRA):module.dropout.train(training)\n        def evaluate(net,head,joint):\n            mode(net,head,False);parts=[];losses=[];start=time.perf_counter()\n            with torch.no_grad():\n                for i in range(0,950,16):\n                    ids=slice(i,min(i+16,950));pred=head(features(net,caches[\'dev\'],ids,joint))\n                    assert torch.isfinite(pred).all()\n                    parts.append(pred.double());losses.append((float(F.smooth_l1_loss(pred,caches[\'dev\'][\'target\'][ids],beta=1)),len(pred)))\n            loc=torch.cat(parts).cpu().numpy()\n            prices=last[:,None]*(1+loc*scalers[\'return_scale\']/10000)\n            return prices,sum(v*n for v,n in losses)/950,(time.perf_counter()-start)/950\n        references={\'Persistencia\':np.repeat(last[:,None],4,axis=1)}\n        for seed in P[\'seeds\']:\n            frame=pd.read_parquet(verified3(f\'metricas/Head_Huber_s{seed}.parquet\'))\n            assert np.array_equal(frame.pivot(index=\'window\',columns=\'horizon\',values=\'truth\').sort_index().to_numpy(),truth)\n            references[f\'Head_Huber_s{seed}\']=frame.pivot(index=\'window\',columns=\'horizon\',values=\'prediction\').sort_index().to_numpy()\n\n        def rng_state(generator):\n            n=np.random.get_state()\n            return {\'python\':random.getstate(),\'numpy_global\':[n[0],n[1].tolist(),n[2],n[3],n[4]],\'order\':generator.bit_generator.state,\'cpu\':torch.get_rng_state(),\'cuda\':torch.cuda.get_rng_state_all()}\n        def restore_rng(state,generator):\n            random.setstate(state[\'python\']);n=state[\'numpy_global\'];np.random.set_state((n[0],np.asarray(n[1],dtype=np.uint32),n[2],n[3],n[4]))\n            generator.bit_generator.state=state[\'order\'];torch.set_rng_state(state[\'cpu\'].cpu());torch.cuda.set_rng_state_all([t.cpu() for t in state[\'cuda\']])\n        def verify_commit(folder):\n            commit=load_json(folder/\'commit.json\')\n            assert commit[\'fingerprint\']==fingerprint and commit[\'source_sha256\']==M10_SOURCE_SHA\n            assert digest(folder/\'checkpoint.pt\')==commit[\'checkpoint_sha256\']\n            return commit\n        def save_checkpoint(folder,step,net,head,opt,generator,curves,order_trace,arm,seed):\n            dest=folder/\'checkpoints\'/f\'step_{step:06d}\'\n            dest.mkdir(parents=True,exist_ok=False)\n            packet={\'step\':step,\'arm\':arm,\'seed\':seed,\'fingerprint\':fingerprint,\'source_sha256\':M10_SOURCE_SHA,\n                    \'head\':{k:v.detach().cpu() for k,v in head.state_dict().items()},\n                    \'adapter\':{k:v.detach().cpu() for k,v in net.state_dict().items() if \'lora_\' in k},\n                    \'optimizer\':opt.state_dict(),\'rng\':rng_state(generator),\'curves\':curves,\'order_trace\':order_trace,\n                    \'base_hash\':P[\'base_hash\'],\'tokenizer_hash\':P[\'tokenizer_hash\']}\n            b=io.BytesIO();torch.save(packet,b);put(dest/\'checkpoint.pt\',b.getvalue())\n            loaded=torch.load(dest/\'checkpoint.pt\',map_location=\'cpu\',weights_only=True)\n            assert loaded[\'step\']==step and all(torch.equal(v,loaded[\'head\'][k]) for k,v in packet[\'head\'].items())\n            put_json(dest/\'commit.json\',{\'step\':step,\'fingerprint\':fingerprint,\'source_sha256\':M10_SOURCE_SHA,\'checkpoint_sha256\':digest(dest/\'checkpoint.pt\')})\n            progress(stage=\'checkpoint_committed\',arm=arm,seed=seed,step=step,loss=curves[-1][\'loss\'] if curves else None)\n\n        predictions={};curves_by_run={};timings={}\n        for arm in (\'control_head_only\',\'joint_QV_head\'):\n            joint=arm==\'joint_QV_head\'\n            for seed in P[\'seeds\']:\n                folder=out/arm/f\'seed_{seed}\';folder.mkdir(parents=True,exist_ok=True)\n                run_name=f\'{arm}_s{seed}\'\n                if (folder/\'completed.json\').exists():\n                    done=load_json(folder/\'completed.json\')\n                    for rel,sha in done[\'hashes\'].items():assert digest(folder/rel)==sha\n                    with np.load(folder/\'predictions.npz\',allow_pickle=False) as z:predictions[run_name]=z[\'prediction\']\n                    curves_by_run[run_name]=load_json(folder/\'curves.json\');timings[run_name]=done[\'seconds_per_window\']\n                    result[\'runs\'].append(done);progress(stage=\'completed_run_reused\',arm=arm,seed=seed);continue\n                random.seed(seed);np.random.seed(seed);torch.manual_seed(seed);torch.cuda.manual_seed_all(seed)\n                generator=np.random.default_rng(seed)\n                net=copy.deepcopy(base) if joint else base\n                if joint:\n                    for name in P[\'arms\'][arm][\'lora_targets\']:\n                        parent,leaf=name.rsplit(\'.\',1);obj=net.get_submodule(parent);setattr(obj,leaf,LoRA(getattr(obj,leaf)))\n                head=copy.deepcopy(session[\'heads\'][seed]).requires_grad_(True)\n                trainable=[p for p in net.parameters() if p.requires_grad]+list(head.parameters())\n                assert sum(p.numel() for p in trainable)==P[\'arms\'][arm][\'trainable_parameters\']\n                groups=[{\'params\':head.parameters(),\'lr\':3e-4}]\n                if joint:groups.append({\'params\':[p for p in net.parameters() if p.requires_grad],\'lr\':1e-4})\n                opt=torch.optim.AdamW(groups,weight_decay=0)\n                step=0;curves=[];order_trace=[]\n                existing=sorted((folder/\'checkpoints\').glob(\'step_*\')) if (folder/\'checkpoints\').exists() else []\n                if existing:\n                    for checkpoint in existing:verify_commit(checkpoint)\n                    packet=torch.load(existing[-1]/\'checkpoint.pt\',map_location=\'cpu\',weights_only=True)\n                    assert packet[\'arm\']==arm and packet[\'seed\']==seed\n                    head.load_state_dict(packet[\'head\'],strict=True)\n                    sd=net.state_dict();assert set(packet[\'adapter\'])=={k for k in sd if \'lora_\' in k};sd.update(packet[\'adapter\']);net.load_state_dict(sd,strict=True)\n                    opt.load_state_dict(packet[\'optimizer\']);restore_rng(packet[\'rng\'],generator)\n                    step=packet[\'step\'];curves=packet[\'curves\'];order_trace=packet[\'order_trace\']\n                    assert 0<=step<=300\n                    progress(stage=\'resume_verified\',arm=arm,seed=seed,step=step)\n                else:\n                    pred0,loss0,_=evaluate(net,head,joint)\n                    delta=np.abs(pred0-references[f\'Head_Huber_s{seed}\'])\n                    assert delta.max()<=.001 and delta.mean()<=.00001,\'Step-zero mismatch\'\n                    put_npz(folder/\'step0.npz\',prediction=pred0,truth=truth)\n                    put_json(folder/\'step0_metrics.json\',{\'MAE\':float(abs(pred0-truth).mean()),\'loss\':loss0,\'max_diff\':float(delta.max()),\'mean_diff\':float(delta.mean())})\n                    save_checkpoint(folder,0,net,head,opt,generator,curves,order_trace,arm,seed)\n                mode(net,head,True)\n                started=time.perf_counter()\n                while step<300:\n                    ids=generator.integers(0,8428,size=64);opt.zero_grad(set_to_none=True);total=0.\n                    for j in range(4):\n                        rows=ids[j*16:(j+1)*16]\n                        pred=head(features(net,caches[\'train\'],rows,joint))\n                        loss=F.smooth_l1_loss(pred,caches[\'train\'][\'target\'][rows],beta=1)\n                        assert torch.isfinite(loss),\'Nonfinite loss\'\n                        (loss/4).backward();total+=float(loss.detach())/4\n                    assert all(p.grad is not None and torch.isfinite(p.grad).all() for p in trainable),\'Invalid/missing gradient\'\n                    assert sum(float(p.grad.abs().sum()) for p in head.parameters())>0,\'Zero head gradients\'\n                    if joint:\n                        assert all(p.grad.abs().sum()>0 for n,p in net.named_parameters() if \'lora_B\' in n),\'Zero LoRA B gradient\'\n                        if step>0:assert any(p.grad.abs().sum()>0 for n,p in net.named_parameters() if \'lora_A\' in n),\'Zero LoRA A gradient after first update\'\n                    assert all(p.grad is None for n,p in net.named_parameters() if \'lora_\' not in n)\n                    assert all(p.grad is None for p in tok.parameters())\n                    norm=nn.utils.clip_grad_norm_(trainable,1.,error_if_nonfinite=True)\n                    opt.step();step+=1\n                    assert all(torch.isfinite(p).all() for p in trainable),\'Nonfinite parameters\'\n                    curves.append({\'step\':step,\'loss\':total,\'gradient_norm\':float(norm),\'elapsed_seconds_this_attempt\':time.perf_counter()-started})\n                    order_trace.append(hashlib.sha256(ids.astype(\'<i8\').tobytes()).hexdigest())\n                    if step%25==0:save_checkpoint(folder,step,net,head,opt,generator,curves,order_trace,arm,seed)\n                pred,dev_loss,latency=evaluate(net,head,joint)\n                assert net_hash(net,exclude_lora=joint)==P[\'base_hash\'],\'Backbone changed\'\n                put_npz(folder/\'predictions.npz\',prediction=pred,truth=truth,last=last)\n                put_json(folder/\'curves.json\',curves);put_json(folder/\'training_order.json\',order_trace)\n                put_json(folder/\'final_metrics.json\',{\'MAE\':float(abs(pred-truth).mean()),\'loss\':dev_loss,\'seconds_per_window\':latency})\n                files=[p for p in folder.rglob(\'*\') if p.is_file()]\n                done={\'arm\':arm,\'seed\':seed,\'status\':\'COMPLETED\',\'step\':300,\'MAE\':float(abs(pred-truth).mean()),\'seconds_per_window\':latency,\n                      \'hashes\':{str(p.relative_to(folder)):digest(p) for p in files}}\n                put_json(folder/\'completed.json\',done)\n                predictions[run_name]=pred;curves_by_run[run_name]=curves;timings[run_name]=latency;result[\'runs\'].append(done)\n                progress(stage=\'run_completed\',arm=arm,seed=seed,MAE=done[\'MAE\'])\n                del head,opt,trainable,net;gc.collect();torch.cuda.empty_cache()\n        for seed in P[\'seeds\']:\n            assert load_json(out/\'control_head_only\'/f\'seed_{seed}\'/\'training_order.json\')==load_json(out/\'joint_QV_head\'/f\'seed_{seed}\'/\'training_order.json\')\n        # Evaluate and plot only persisted real predictions; no further fitting or selection.\n        evaluation_ns={}\n        exec(compile(M10_EVALUATION_SOURCE,\'m10_evaluation\',\'exec\'),evaluation_ns)\n        result[\'evaluation\']=evaluation_ns[\'m10_evaluate\'](out,root,P,predictions,references,truth,last,dev_index,curves_by_run,timings)\n        result[\'status\']=\'COMPLETED\';result[\'runs\']=[{k:v for k,v in r.items() if k!=\'hashes\'} for r in result[\'runs\']]\n        assert net_hash(base)==P[\'base_hash\'] and net_hash(tok)==P[\'tokenizer_hash\']\n    except Exception as exc:\n        result[\'status\']=\'BLOCKED\';result[\'error\']=type(exc).__name__+\': \'+str(exc)\n        result[\'traceback\']=traceback.format_exc()\n    finally:\n        random.setstate(saved_rng[0]);np.random.set_state(saved_rng[1]);torch.set_rng_state(saved_rng[2]);torch.cuda.set_rng_state_all(saved_rng[3])\n        torch.use_deterministic_algorithms(old_deterministic);torch.backends.cuda.matmul.allow_tf32=old_tf32[0];torch.backends.cudnn.allow_tf32=old_tf32[1]\n        result[\'production_weights_unchanged\']=net_hash(base)==P[\'base_hash\'] and net_hash(tok)==P[\'tokenizer_hash\']\n        put_json(out/f\'attempts/{attempt}/result.json\',result)\n        if load_json(lock)==owner:lock.unlink()\n        files=[p for p in out.rglob(\'*\') if p.is_file()]\n        put_json(out/f\'attempts/{attempt}/manifest.json\',{str(p.relative_to(out)):digest(p) for p in files})\n        print(\'M10_PHASE_V_RESULT \'+json.dumps(result),flush=True)\n    return result\n\nM10_RESULT=m10_execute(AXXEL_SESSION)\n'
M10_SOURCE_SHA='7529b75140fd84bff4cf01819ce552637868bc0bfba8740a537b2e850048bc6b'
# M10_PHASE_V_JOINT_RETURN_V1
"""Explicitly authorized six-run experiment; never invoked by daily start.
Configuration, audited data source, activity check and source hashes are embedded by builder.
"""
def m10_execute(session):
    import copy, datetime, gc, hashlib, io, json, math, os, random, time, traceback
    from pathlib import Path
    import numpy as np
    import pandas as pd
    import torch
    from torch import nn
    from torch.nn import functional as F
    from torch.utils.data import default_collate

    P=M10_PROTOCOL
    assert M10_AUTHORIZED is True and P['experiment']=='M06_FV_JOINT_RETURN_V1'
    assert P['budget']['additional_steps_each']==300 and P['budget']['microbatch']==16 and P['budget']['accumulation']==4
    assert P['seeds']==[271828,271829,271830] and P['optimizer']['weight_decay']==0
    root=Path(P['canonical_run'])
    result={'timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'RUNNING','runs':[],
            'test_read':False,'orders_enabled':False,'training_authorized':True}
    def digest(path):
        h=hashlib.sha256()
        with Path(path).open('rb') as f:
            for b in iter(lambda:f.read(1048576),b''):h.update(b)
        return h.hexdigest()
    def canonical(value):return json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
    def net_hash(net,exclude_lora=False):
        h=hashlib.sha256()
        for name,t in sorted(net.state_dict().items()):
            if exclude_lora and 'lora_' in name:continue
            name=name.replace('.base.', '.') if exclude_lora else name
            h.update(name.encode());h.update(str(tuple(t.shape)).encode());h.update(t.detach().cpu().contiguous().numpy().tobytes())
        return h.hexdigest()
    def put(path,data):
        path=Path(path)
        if path.exists():
            assert path.read_bytes()==data,'Conflicting existing artifact: '+str(path)
            return
        path.parent.mkdir(parents=True,exist_ok=True)
        with path.open('xb') as f:f.write(data);f.flush();os.fsync(f.fileno())
        assert digest(path)==hashlib.sha256(data).hexdigest()
    def put_json(path,data):put(path,canonical(data))
    def put_npz(path,**arrays):
        b=io.BytesIO();np.savez_compressed(b,**arrays);put(path,b.getvalue())
    def load_json(path):return json.loads(Path(path).read_text())
    def progress(**values):print('M10_PROGRESS '+json.dumps(values),flush=True)

    # Repeat only volatile readiness checks; historical experiments are never invoked.
    activity_ns={'__name__':'m10_activity'}
    exec(compile(M10_ACTIVITY_SOURCE,'m10_activity','exec'),activity_ns)
    activity=activity_ns['m09_activity_gate']({'AXXEL_SESSION':session})
    assert activity['status']=='PASS_CURRENT_ACTIVITY',activity['blockers']
    assert os.path.ismount('/content/drive') and torch.cuda.is_available()
    base,tok=session['model'],session['tokenizer']
    assert net_hash(base)==P['base_hash'] and net_hash(tok)==P['tokenizer_hash']
    assert all(not p.requires_grad and p.grad is None for net in (base,tok) for p in net.parameters())
    assert digest(root/'informes/PROTOCOLO_FASE_V_JOINT_PROPUESTO_20261120.json')==M10_PROTOCOL_SHA
    manifest3=load_json(root/'fase_III/checksums.json')
    assert digest(root/'fase_III/checksums.json')=='731d1c5412d4836e16961ff2e3747e6fd4da124db81eaf20265a638b6c90d7a1'
    def verified3(relative):
        p=root/'fase_III'/relative
        assert digest(p)==manifest3[relative]['sha256'],str(p)
        return p
    for seed in P['seeds']:
        init=P['head_initialization'][str(seed)]
        assert digest(init['path'])==init['sha256']
        packet=torch.load(init['path'],map_location='cpu',weights_only=True)
        assert all(torch.equal(v.cpu(),packet['head'][k]) for k,v in session['heads'][seed].state_dict().items())

    science=copy.deepcopy(P)
    for k in ('created_date_Bogota','status','purpose','canonical_run','output_subdirectory_proposed','training_started'):science.pop(k,None)
    for head in science['head_initialization'].values():head.pop('path');head.pop('model')
    science['execution_source_sha256']=M10_SOURCE_SHA
    science['data_code_sha256']=hashlib.sha256(M10_DATA_SOURCE.encode()).hexdigest()
    fingerprint=hashlib.sha256(canonical(science)).hexdigest()
    registry=root/'fase_V_joint_v1'
    registry.mkdir(exist_ok=True)
    # Any prior registry entry for this protocol with changed code/config is a conflict, not a fresh run.
    for folder in registry.iterdir():
        assert folder.is_dir() and (folder/'config.json').is_file(),'Untracked Phase V artifact: '+str(folder)
        assert folder.name==fingerprint and load_json(folder/'config.json')==science,'Existing Phase V configuration conflict'
    out=registry/fingerprint
    out.mkdir(exist_ok=True)
    put_json(out/'config.json',science)
    put(out/'training_source.py',M10_BODY_SOURCE.encode())
    put(out/'data_source.py',M10_DATA_SOURCE.encode())
    put(out/'evaluation_source.py',M10_EVALUATION_SOURCE.encode())
    put(out/'activity_source.py',M10_ACTIVITY_SOURCE.encode())
    put_json(out/'protocol_original.json',P)
    result['artifact_directory']=str(out);result['scientific_fingerprint']=fingerprint
    attempt=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
    lock=out/'active.lock'
    owner={'pid':os.getpid(),'attempt':attempt,'boot_id':Path('/proc/sys/kernel/random/boot_id').read_text().strip()}
    if lock.exists():raise RuntimeError('Existing execution lock: inspect persisted state before resuming')
    with lock.open('x') as f:json.dump(owner,f)
    saved_rng=(random.getstate(),np.random.get_state(),torch.get_rng_state(),torch.cuda.get_rng_state_all())
    old_deterministic=torch.are_deterministic_algorithms_enabled()
    old_tf32=(torch.backends.cuda.matmul.allow_tf32,torch.backends.cudnn.allow_tf32)
    try:
        os.environ.setdefault('CUBLAS_WORKSPACE_CONFIG',':4096:8')
        torch.use_deterministic_algorithms(True)
        torch.backends.cuda.matmul.allow_tf32=False;torch.backends.cudnn.allow_tf32=False
        base.eval();tok.eval()
        put_json(out/f'attempts/{attempt}/activity.json',activity)
        put_json(out/f'attempts/{attempt}/environment.json',{'torch':str(torch.__version__),'cuda':torch.version.cuda,'gpu':torch.cuda.get_device_name(),'free_total_bytes':torch.cuda.mem_get_info()})
        ns={'__name__':'m10_authorized_data','M6_PREFLIGHT_OK':True,'M6_BASE':root.parents[1],'M6_DIR':root,
            'M6_POLICY':load_json(root/'configuraciones/politica.json'),'torch':torch,'m6_sha':digest}
        assert ns['M6_POLICY']['allowed_source_years']==list(range(2010,2021))
        exec(compile(M10_DATA_SOURCE,'m10_authorized_data','exec'),ns)
        assert digest(root/'auditoria/datasets_autorizados.json')==P['data']['source_manifest_sha256']
        assert ns['M6_SOURCE_MANIFEST']==load_json(root/'auditoria/datasets_autorizados.json')
        pd.testing.assert_frame_equal(ns['m6_ix'],pd.read_parquet(root/'auditoria/ventanas_m06.parquet'))
        train,dev=ns['m6_train'],ns['m6_dev'];dev_index=ns['m6_dev_ix']
        assert len(train)==8428 and len(dev)==950 and dev_index.ny_date.nunique()==243
        scalers=session['scalers']
        scaler_path=verified3('checkpoints/fase_III/7587400db64558e6/train_only_scalers.npz')
        assert digest(scaler_path)==P['shared_model']['scalers_sha256']
        with np.load(scaler_path,allow_pickle=False) as z:
            assert all(np.array_equal(scalers[k],z[k]) for k in z.files)
        mean=torch.as_tensor(scalers['hidden_mean'],device='cuda')
        scale=torch.as_tensor(scalers['hidden_scale'],device='cuda')
        ret_scale=torch.as_tensor(scalers['return_scale'],device='cuda')
        def normalize(h):return ((h.double()-mean).float().double()/scale).float()
        def encode_dataset(ds):
            packs={k:[] for k in ('a','b','stamp','features','truth','last','target')}
            with torch.no_grad():
                for i in range(0,len(ds),16):
                    b={k:v.cuda() for k,v in default_collate([ds[j] for j in range(i,min(i+16,len(ds)))]).items()}
                    a,c=tok.encode(b['x'][:,:56],half=True)
                    stamp=b['stamp'][:,:56]
                    h=base.decode_s1(a,c,stamp=stamp)[1][:,-1]
                    truth=b['truth'][:,:,3].double();last=b['last_close'].double()
                    target=(10000*(truth/last[:,None]-1)/ret_scale).float()
                    for key,value in zip(packs,(a,c,stamp,normalize(h),truth,last,target)):packs[key].append(value.detach())
            return {k:torch.cat(v) for k,v in packs.items()}
        progress(stage='encoding_context_only',train_windows=len(train),dev_windows=len(dev))
        caches={'train':encode_dataset(train),'dev':encode_dataset(dev)}
        truth=caches['dev']['truth'].cpu().numpy();last=caches['dev']['last'].cpu().numpy()
        put_npz(out/'development_index.npz',truth=truth,last=last,session=dev_index.ny_date.to_numpy(dtype=str),hour=dev_index.ny_hour.to_numpy(dtype=str),decision=dev_index.decision_utc.astype(str).to_numpy(dtype=str))

        class LoRA(nn.Module):
            def __init__(self,layer):
                super().__init__();self.base=layer.requires_grad_(False)
                self.lora_A=nn.Parameter(torch.empty(8,layer.in_features,device='cuda'))
                self.lora_B=nn.Parameter(torch.zeros(layer.out_features,8,device='cuda'))
                self.dropout=nn.Dropout(.1);nn.init.kaiming_uniform_(self.lora_A,a=math.sqrt(5))
            def forward(self,x):return self.base(x)+2*F.linear(F.linear(self.dropout(x),self.lora_A),self.lora_B)
        def features(net,cache,ids,joint):
            if not joint:return cache['features'][ids]
            return normalize(net.decode_s1(cache['a'][ids],cache['b'][ids],stamp=cache['stamp'][ids])[1][:,-1])
        def mode(net,head,training):
            net.eval();head.train(training)
            for module in net.modules():
                if isinstance(module,LoRA):module.dropout.train(training)
        def evaluate(net,head,joint):
            mode(net,head,False);parts=[];losses=[];start=time.perf_counter()
            with torch.no_grad():
                for i in range(0,950,16):
                    ids=slice(i,min(i+16,950));pred=head(features(net,caches['dev'],ids,joint))
                    assert torch.isfinite(pred).all()
                    parts.append(pred.double());losses.append((float(F.smooth_l1_loss(pred,caches['dev']['target'][ids],beta=1)),len(pred)))
            loc=torch.cat(parts).cpu().numpy()
            prices=last[:,None]*(1+loc*scalers['return_scale']/10000)
            return prices,sum(v*n for v,n in losses)/950,(time.perf_counter()-start)/950
        references={'Persistencia':np.repeat(last[:,None],4,axis=1)}
        for seed in P['seeds']:
            frame=pd.read_parquet(verified3(f'metricas/Head_Huber_s{seed}.parquet'))
            assert np.array_equal(frame.pivot(index='window',columns='horizon',values='truth').sort_index().to_numpy(),truth)
            references[f'Head_Huber_s{seed}']=frame.pivot(index='window',columns='horizon',values='prediction').sort_index().to_numpy()

        def rng_state(generator):
            n=np.random.get_state()
            return {'python':random.getstate(),'numpy_global':[n[0],n[1].tolist(),n[2],n[3],n[4]],'order':generator.bit_generator.state,'cpu':torch.get_rng_state(),'cuda':torch.cuda.get_rng_state_all()}
        def restore_rng(state,generator):
            random.setstate(state['python']);n=state['numpy_global'];np.random.set_state((n[0],np.asarray(n[1],dtype=np.uint32),n[2],n[3],n[4]))
            generator.bit_generator.state=state['order'];torch.set_rng_state(state['cpu'].cpu());torch.cuda.set_rng_state_all([t.cpu() for t in state['cuda']])
        def verify_commit(folder):
            commit=load_json(folder/'commit.json')
            assert commit['fingerprint']==fingerprint and commit['source_sha256']==M10_SOURCE_SHA
            assert digest(folder/'checkpoint.pt')==commit['checkpoint_sha256']
            return commit
        def save_checkpoint(folder,step,net,head,opt,generator,curves,order_trace,arm,seed):
            dest=folder/'checkpoints'/f'step_{step:06d}'
            dest.mkdir(parents=True,exist_ok=False)
            packet={'step':step,'arm':arm,'seed':seed,'fingerprint':fingerprint,'source_sha256':M10_SOURCE_SHA,
                    'head':{k:v.detach().cpu() for k,v in head.state_dict().items()},
                    'adapter':{k:v.detach().cpu() for k,v in net.state_dict().items() if 'lora_' in k},
                    'optimizer':opt.state_dict(),'rng':rng_state(generator),'curves':curves,'order_trace':order_trace,
                    'base_hash':P['base_hash'],'tokenizer_hash':P['tokenizer_hash']}
            b=io.BytesIO();torch.save(packet,b);put(dest/'checkpoint.pt',b.getvalue())
            loaded=torch.load(dest/'checkpoint.pt',map_location='cpu',weights_only=True)
            assert loaded['step']==step and all(torch.equal(v,loaded['head'][k]) for k,v in packet['head'].items())
            put_json(dest/'commit.json',{'step':step,'fingerprint':fingerprint,'source_sha256':M10_SOURCE_SHA,'checkpoint_sha256':digest(dest/'checkpoint.pt')})
            progress(stage='checkpoint_committed',arm=arm,seed=seed,step=step,loss=curves[-1]['loss'] if curves else None)

        predictions={};curves_by_run={};timings={}
        for arm in ('control_head_only','joint_QV_head'):
            joint=arm=='joint_QV_head'
            for seed in P['seeds']:
                folder=out/arm/f'seed_{seed}';folder.mkdir(parents=True,exist_ok=True)
                run_name=f'{arm}_s{seed}'
                if (folder/'completed.json').exists():
                    done=load_json(folder/'completed.json')
                    for rel,sha in done['hashes'].items():assert digest(folder/rel)==sha
                    with np.load(folder/'predictions.npz',allow_pickle=False) as z:predictions[run_name]=z['prediction']
                    curves_by_run[run_name]=load_json(folder/'curves.json');timings[run_name]=done['seconds_per_window']
                    result['runs'].append(done);progress(stage='completed_run_reused',arm=arm,seed=seed);continue
                random.seed(seed);np.random.seed(seed);torch.manual_seed(seed);torch.cuda.manual_seed_all(seed)
                generator=np.random.default_rng(seed)
                net=copy.deepcopy(base) if joint else base
                if joint:
                    for name in P['arms'][arm]['lora_targets']:
                        parent,leaf=name.rsplit('.',1);obj=net.get_submodule(parent);setattr(obj,leaf,LoRA(getattr(obj,leaf)))
                head=copy.deepcopy(session['heads'][seed]).requires_grad_(True)
                trainable=[p for p in net.parameters() if p.requires_grad]+list(head.parameters())
                assert sum(p.numel() for p in trainable)==P['arms'][arm]['trainable_parameters']
                groups=[{'params':head.parameters(),'lr':3e-4}]
                if joint:groups.append({'params':[p for p in net.parameters() if p.requires_grad],'lr':1e-4})
                opt=torch.optim.AdamW(groups,weight_decay=0)
                step=0;curves=[];order_trace=[]
                existing=sorted((folder/'checkpoints').glob('step_*')) if (folder/'checkpoints').exists() else []
                if existing:
                    for checkpoint in existing:verify_commit(checkpoint)
                    packet=torch.load(existing[-1]/'checkpoint.pt',map_location='cpu',weights_only=True)
                    assert packet['arm']==arm and packet['seed']==seed
                    head.load_state_dict(packet['head'],strict=True)
                    sd=net.state_dict();assert set(packet['adapter'])=={k for k in sd if 'lora_' in k};sd.update(packet['adapter']);net.load_state_dict(sd,strict=True)
                    opt.load_state_dict(packet['optimizer']);restore_rng(packet['rng'],generator)
                    step=packet['step'];curves=packet['curves'];order_trace=packet['order_trace']
                    assert 0<=step<=300
                    progress(stage='resume_verified',arm=arm,seed=seed,step=step)
                else:
                    pred0,loss0,_=evaluate(net,head,joint)
                    delta=np.abs(pred0-references[f'Head_Huber_s{seed}'])
                    assert delta.max()<=.001 and delta.mean()<=.00001,'Step-zero mismatch'
                    put_npz(folder/'step0.npz',prediction=pred0,truth=truth)
                    put_json(folder/'step0_metrics.json',{'MAE':float(abs(pred0-truth).mean()),'loss':loss0,'max_diff':float(delta.max()),'mean_diff':float(delta.mean())})
                    save_checkpoint(folder,0,net,head,opt,generator,curves,order_trace,arm,seed)
                mode(net,head,True)
                started=time.perf_counter()
                while step<300:
                    ids=generator.integers(0,8428,size=64);opt.zero_grad(set_to_none=True);total=0.
                    for j in range(4):
                        rows=ids[j*16:(j+1)*16]
                        pred=head(features(net,caches['train'],rows,joint))
                        loss=F.smooth_l1_loss(pred,caches['train']['target'][rows],beta=1)
                        assert torch.isfinite(loss),'Nonfinite loss'
                        (loss/4).backward();total+=float(loss.detach())/4
                    assert all(p.grad is not None and torch.isfinite(p.grad).all() for p in trainable),'Invalid/missing gradient'
                    assert sum(float(p.grad.abs().sum()) for p in head.parameters())>0,'Zero head gradients'
                    if joint:
                        assert all(p.grad.abs().sum()>0 for n,p in net.named_parameters() if 'lora_B' in n),'Zero LoRA B gradient'
                        if step>0:assert any(p.grad.abs().sum()>0 for n,p in net.named_parameters() if 'lora_A' in n),'Zero LoRA A gradient after first update'
                    assert all(p.grad is None for n,p in net.named_parameters() if 'lora_' not in n)
                    assert all(p.grad is None for p in tok.parameters())
                    norm=nn.utils.clip_grad_norm_(trainable,1.,error_if_nonfinite=True)
                    opt.step();step+=1
                    assert all(torch.isfinite(p).all() for p in trainable),'Nonfinite parameters'
                    curves.append({'step':step,'loss':total,'gradient_norm':float(norm),'elapsed_seconds_this_attempt':time.perf_counter()-started})
                    order_trace.append(hashlib.sha256(ids.astype('<i8').tobytes()).hexdigest())
                    if step%25==0:save_checkpoint(folder,step,net,head,opt,generator,curves,order_trace,arm,seed)
                pred,dev_loss,latency=evaluate(net,head,joint)
                assert net_hash(net,exclude_lora=joint)==P['base_hash'],'Backbone changed'
                put_npz(folder/'predictions.npz',prediction=pred,truth=truth,last=last)
                put_json(folder/'curves.json',curves);put_json(folder/'training_order.json',order_trace)
                put_json(folder/'final_metrics.json',{'MAE':float(abs(pred-truth).mean()),'loss':dev_loss,'seconds_per_window':latency})
                files=[p for p in folder.rglob('*') if p.is_file()]
                done={'arm':arm,'seed':seed,'status':'COMPLETED','step':300,'MAE':float(abs(pred-truth).mean()),'seconds_per_window':latency,
                      'hashes':{str(p.relative_to(folder)):digest(p) for p in files}}
                put_json(folder/'completed.json',done)
                predictions[run_name]=pred;curves_by_run[run_name]=curves;timings[run_name]=latency;result['runs'].append(done)
                progress(stage='run_completed',arm=arm,seed=seed,MAE=done['MAE'])
                del head,opt,trainable,net;gc.collect();torch.cuda.empty_cache()
        for seed in P['seeds']:
            assert load_json(out/'control_head_only'/f'seed_{seed}'/'training_order.json')==load_json(out/'joint_QV_head'/f'seed_{seed}'/'training_order.json')
        # Evaluate and plot only persisted real predictions; no further fitting or selection.
        evaluation_ns={}
        exec(compile(M10_EVALUATION_SOURCE,'m10_evaluation','exec'),evaluation_ns)
        result['evaluation']=evaluation_ns['m10_evaluate'](out,root,P,predictions,references,truth,last,dev_index,curves_by_run,timings)
        result['status']='COMPLETED';result['runs']=[{k:v for k,v in r.items() if k!='hashes'} for r in result['runs']]
        assert net_hash(base)==P['base_hash'] and net_hash(tok)==P['tokenizer_hash']
    except Exception as exc:
        result['status']='BLOCKED';result['error']=type(exc).__name__+': '+str(exc)
        result['traceback']=traceback.format_exc()
    finally:
        random.setstate(saved_rng[0]);np.random.set_state(saved_rng[1]);torch.set_rng_state(saved_rng[2]);torch.cuda.set_rng_state_all(saved_rng[3])
        torch.use_deterministic_algorithms(old_deterministic);torch.backends.cuda.matmul.allow_tf32=old_tf32[0];torch.backends.cudnn.allow_tf32=old_tf32[1]
        result['production_weights_unchanged']=net_hash(base)==P['base_hash'] and net_hash(tok)==P['tokenizer_hash']
        put_json(out/f'attempts/{attempt}/result.json',result)
        if load_json(lock)==owner:lock.unlink()
        files=[p for p in out.rglob('*') if p.is_file()]
        put_json(out/f'attempts/{attempt}/manifest.json',{str(p.relative_to(out)):digest(p) for p in files})
        print('M10_PHASE_V_RESULT '+json.dumps(result),flush=True)
    return result

M10_RESULT=m10_execute(AXXEL_SESSION)
